<script setup>
import {ref,computed} from 'vue'
import Icon from '../Icon.vue'
import SocialLinks from './SocialLinks.vue'
import ProfileEditor from './ProfileEditor.vue'
import FollowUpdates from './FollowUpdates.vue'
import {community,approveProfile,relationship,changeLink} from './community'
import {isDemo,call} from '../service'
const props=defineProps({member:Object,marketplace:Object}),emit=defineEmits(['navigate','notify'])
const db=ref(isDemo?community():{profiles:[],pending:[],links:[]}),editingProfile=ref(false),query=ref(''),selected=ref(null),message=ref(''),joinType=ref(''),shared=ref(''),nativeFollowers=ref(0),nativeOwns=ref(false),catalogue=ref({classes:[],teachers:[]}),catalogueBusy=ref(false)
const identity=computed(()=>isDemo?props.member.name:props.member.user)
const owner=computed(()=>props.member.role==='PlatformAdmin'),profiles=computed(()=>db.value.profiles.filter(p=>p.kind!=='Student'&&(p.username+' '+p.display_name+' '+p.subjects).toLowerCase().includes(query.value.toLowerCase().replace(/^@/,''))))
const followers=p=>db.value.links.filter(l=>l.profile===p.name&&l.kind==='Follow'&&l.status==='Active').length
const mine=(p,kind)=>db.value.links.find(l=>l.profile===p.name&&l.user===identity.value&&l.kind===kind)
const classList=computed(()=>!isDemo?catalogue.value.classes:(props.marketplace?.classes||[]).filter(c=>c.provider===selected.value?.name||selected.value?.kind==='Teacher'&&c.teacher===selected.value?.display_name))
const affiliateTeachers=computed(()=>{const ids=new Set((props.marketplace?.classes||[]).filter(c=>c.provider===selected.value?.name).map(c=>c.teacher));return [...ids]})
const owns=p=>!isDemo?nativeOwns.value:p.user===identity.value||p.owner===identity.value||(props.member.role==='Admin'&&p.name==='teen-academy')
async function load(){if(isDemo){db.value=community();return}try{const p=await call(owner.value?'pending':'search',{query:query.value},'profiles');if(owner.value)db.value.pending=p;else db.value.profiles=p}catch(e){message.value=e.message}}
async function view(p){selected.value=p;shared.value='';catalogue.value={classes:[],teachers:[]};catalogueBusy.value=true;if(!isDemo){try{const [r,c]=await Promise.all([call('relationships',{profile:p.name},'profiles'),call('detail',{profile:p.name},'catalog')]);nativeFollowers.value=r.followers;nativeOwns.value=r.owns_profile;db.value.links=r.relationships;catalogue.value=c;selected.value={...p,...c.profile}}catch(e){message.value=e.message}}catalogueBusy.value=false}
async function follow(p){try{const l=mine(p,'Follow');if(l?.status==='Active'){if(isDemo)changeLink(l.name,'Left');else await call('change_relationship',{relationship:l.name,status:'Left'},'profiles')}else if(isDemo)relationship(p.name,props.member.name,'Follow');else await call('relate',{profile:p.name,kind:'Follow'},'profiles');await load();if(!isDemo)await view(p);message.value='Follow preference updated. Following gives news updates; it does not unlock paid classes.'}catch(e){message.value=e.message}}
async function join(p){try{const kind=props.member.role==='Teacher'?'Teacher membership':'Student join';if(isDemo)relationship(p.name,props.member.name,kind);else await call('relate',{profile:p.name,kind},'profiles');await load();if(!isDemo)await view(p);message.value='Request sent. The provider will review your membership.'}catch(e){message.value=e.message}}
async function review(p,status){try{if(isDemo)approveProfile(p.name,status);else await call('review',{profile:p.name,decision:status,reason:'Reviewed by platform owner'},'profiles');await load();message.value=status==='Verified'?'Verified badge and unique code issued.':'Profile request rejected.'}catch(e){message.value=e.message}}
async function update(l,status){try{if(isDemo)changeLink(l.name,status);else await call('change_relationship',{relationship:l.name,status},'profiles');await load();if(!isDemo&&selected.value)await view(selected.value)}catch(e){message.value=e.message}}
async function share(p){shared.value=location.origin+'/campus?profile='+encodeURIComponent(p.username)+'#connections';if(isDemo)shared.value=location.origin+'/?profile='+encodeURIComponent(p.username)+'#connections';try{await navigator.clipboard.writeText(shared.value);message.value='Profile link copied. Share it with your students.'}catch{message.value='Copy the profile link shown below.'}}
async function enroll(c){try{if(c.programme){emit('navigate','programmes');return}if(!isDemo)await call('join_class',{classroom:c.name},'catalog');else await call('marketplace_enroll',{classroom:c.name});message.value='Class enrollment created. Open Class fees to complete payment; no money has been charged.'}catch(e){message.value=e.message}}
load().then(()=>{const username=new URLSearchParams(location.search).get('profile');if(username){const p=db.value.profiles.find(p=>p.username===username);if(p)view(p)}})
</script>
<template><section class="connections-page"><div class="page-heading"><div><span class="eyebrow">GOOD PEOPLE. MEANINGFUL CONNECTIONS.</span><h1>{{owner?'A little trust goes a long way.':'Find your learning people.'}}</h1><p>{{owner?'Review provider profiles and issue their verified identity.':'Find a username, follow their news, or request to join their learning community.'}}</p></div><button v-if="member.role==='Teacher'||member.role==='Admin'" class="button primary" @click="editingProfile=!editingProfile">My profile <Icon name="Pencil" :size="16"/></button></div><p v-if="message" class="form-note" role="status">{{message}}</p><ProfileEditor v-if="editingProfile" :member="member" @navigate="emit('navigate',$event)" @saved="editingProfile=false;load()"/><template v-if="owner"><section class="panel review-providers"><h2>Provider verification requests</h2><article v-for="p in db.pending.filter(p=>p.status==='Pending')" class="connection-row"><div><h3>{{p.display_name}}</h3><p>@{{p.username}} · {{p.kind}} · {{p.country}}</p></div><button class="button primary" @click="review(p,'Verified')">Verify & issue code</button><button class="button subtle" @click="review(p,'Rejected')">Reject</button></article><p v-if="!db.pending.some(p=>p.status==='Pending')">No provider profiles waiting for approval.</p><p class="field-help">{{isDemo?'These are fictional preview approvals.':'Review business/teacher evidence before issuing verification.'}}</p></section></template><template v-else><label class="search connection-search"><Icon name="Search"/><input v-model="query" @input="!isDemo&&load()" placeholder="Find @username, institute or teacher" aria-label="Find profiles"></label><template v-if="!selected"><div v-if="!profiles.length" class="panel directory-empty"><Icon name="Sprout" :size="32"/><h2>A little space for good people.</h2><p>{{query?'No verified profiles match your search. Try a name or username.':'Verified teachers and institutes will appear here when their profiles are approved.'}}</p></div><div class="connection-grid"><article v-for="p in profiles" class="panel connection-card"><img v-if="p.cover_image" class="directory-cover" :src="p.cover_image" alt="" loading="lazy"><div class="connection-avatar"><img v-if="p.profile_image" :src="p.profile_image" alt="" loading="lazy"><span v-else>{{p.display_name.slice(0,1)}}</span></div><span class="badge violet">{{p.kind}}</span><h2>{{p.display_name}}</h2><p>@{{p.username}}</p><SocialLinks :profile="p"/><span class="connection-verification"><Icon name="BadgeCheck" :size="16"/>{{p.code}} · {{isDemo?'Demo verified':'Verified'}}</span><p>{{followers(p)}} followers · {{p.country}}</p><button class="button primary" @click="view(p)">View profile <Icon name="ArrowRight" :size="16"/></button></article></div></template><template v-else><button class="text-button" @click="selected=null">← All profiles</button><div class="directory-hero-cover" :class="{empty:!selected.cover_image}"><img v-if="selected.cover_image" :src="selected.cover_image" alt="Profile cover"></div><div class="provider-header-socials"><SocialLinks :profile="selected"/></div><section class="connection-hero"><div class="connection-avatar big"><img v-if="selected.profile_image" :src="selected.profile_image" alt="Profile picture"><span v-else>{{selected.display_name.slice(0,1)}}</span></div><div><span class="eyebrow">{{selected.kind==='Teacher'?'MEET YOUR TEACHER':'YOUR LEARNING COMMUNITY'}}</span><h1>{{selected.display_name}}</h1><p>{{selected.tagline}}</p><p>@{{selected.username}} · {{selected.country}}</p><p v-if="selected.qualifications">{{selected.qualifications}}</p><div class="inline wrap"><span class="badge violet"><Icon name="BadgeCheck" :size="16"/>{{selected.code}} · {{isDemo?'Demo verified':'Verified'}}</span><span>{{isDemo?followers(selected):nativeFollowers}} followers</span><span>{{classList.length}} published classes</span></div></div><div class="connection-hero-actions"><button class="button subtle" @click="follow(selected)">{{mine(selected,'Follow')?.status==='Active'?'Following ✓':'Follow updates'}}</button><button v-if="['Student','Teacher'].includes(member.role)" class="button primary" :disabled="['Active','Pending'].includes(mine(selected,member.role==='Teacher'?'Teacher membership':'Student join')?.status)" @click="join(selected)">{{mine(selected,member.role==='Teacher'?'Teacher membership':'Student join')?.status||'Request to join'}}</button><button class="text-button" @click="share(selected)"><Icon name="Share2" :size="15"/>Share profile</button></div></section><input v-if="shared" readonly :value="shared" aria-label="Shareable profile link" class="shared-profile"><div class="connection-details"><section class="panel"><h2>About {{selected.kind==='Teacher'?'me':'our community'}}</h2><p>{{selected.bio}}</p><dl><dt>Subjects & curriculum</dt><dd>{{selected.subjects||selected.curriculum||selected.education_system}}</dd><dt>Grades / levels</dt><dd>{{selected.grades||'See each class'}}</dd><dt>Teaching languages</dt><dd>{{selected.languages}}</dd></dl><h3 v-if="selected.kind==='Teacher'">Institute memberships</h3><p v-if="selected.kind==='Teacher'">Independent teaching and approved institute memberships can coexist. Earnings follow the owner of each class.</p><article v-for="l in db.links.filter(l=>l.user===identity&&l.kind==='Teacher membership'&&['Active','Pending'].includes(l.status))" class="connection-row"><span>{{db.profiles.find(p=>p.name===l.profile)?.display_name}} · {{l.status}}</span><button class="text-button" @click="update(l,'Left')">Leave institute</button></article></section><section><h2>{{selected.kind==='Institute'?'Meet the teaching team':'Find your class'}}</h2><div v-if="selected.kind==='Institute'&&!isDemo" class="teacher-mini-grid"><article v-for="teacher in catalogue.teachers" :key="teacher.name" class="panel"><img v-if="teacher.cover_image" :src="teacher.cover_image" class="directory-cover" alt="" loading="lazy"><div class="connection-avatar"><img v-if="teacher.profile_image" :src="teacher.profile_image" alt="" loading="lazy"><span v-else>{{teacher.display_name.slice(0,1)}}</span></div><h3>{{teacher.display_name}}</h3><p>{{teacher.qualifications}}</p><p>@{{teacher.username}}</p><SocialLinks :profile="teacher"/><button class="button subtle" @click="view(teacher)">See classes →</button></article></div><div v-if="selected.kind==='Institute'&&isDemo" class="teacher-mini-grid"><article v-for="name in affiliateTeachers" class="panel"><span class="connection-avatar">{{name.slice(0,1)}}</span><h3>{{name}}</h3><button v-if="db.profiles.some(p=>p.display_name===name)" class="text-button" @click="view(db.profiles.find(p=>p.display_name===name))">View teacher</button><small v-else>Profile not published yet</small></article></div><article v-for="c in classList" class="panel connection-class"><img v-if="c.cover_image" :src="c.cover_image" class="directory-cover" alt="" loading="lazy"><span class="badge violet">{{c.grade||c.level}} · {{c.teaching_medium||c.medium}}</span><span class="badge">{{c.fee_mode||'Paid'}} class</span><h3>{{c.title}}</h3><p>{{c.schedule_label||'Schedule to be announced'}}</p><strong>{{c.billing_type==='Programme module'?'Included in programme':c.billing_type==='Monthly'?'Monthly class · choose your paid month':'Course enrollment'}}</strong><p class="field-help">{{c.fee_mode==='Free'?'No teaching fee. An assigned platform fee may still apply.':'Your assigned agreement applies.'}} Review the full amount before paying.</p><button v-if="member.role==='Student'&&!selected.is_school" class="button primary" @click="enroll(c)">{{c.programme?'View complete programme →':'Join class →'}}</button></article><p v-if="catalogueBusy" role="status">Loading published classes…</p><p v-if="!catalogueBusy&&!classList.length" class="field-help">Classes will appear when this provider publishes them.</p></section></div><FollowUpdates v-if="owns(selected)" :member="member" :profile="selected"/><section v-if="owns(selected)" class="panel review-providers"><h2>Membership requests & people</h2><article v-for="l in db.links.filter(l=>l.profile===selected.name&&l.kind!=='Follow'&&['Pending','Active'].includes(l.status))" class="connection-row"><span>{{l.user}} · {{l.kind}} · {{l.status}}</span><button v-if="l.status==='Pending'" class="button primary" @click="update(l,'Active')">Approve request</button><button class="button subtle" @click="update(l,l.status==='Active'?'Removed':'Rejected')">{{l.status==='Active'?'Remove membership':'Reject request'}}</button></article><p>Students register themselves. Share your profile to invite them to follow or request membership.</p></section></template></template></section></template>
<style>.connection-search{max-width:580px;margin:25px 0}.connection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px}.connection-card{padding:28px;border-radius:27px!important;display:flex;flex-direction:column;gap:15px}.connection-card h2{font-size:20px}.connection-card p{font-size:12px}.connection-avatar{width:57px;height:60px;display:grid;place-items:center;border-radius:21px;background:linear-gradient(135deg,#dfcff5,#bca4dd);font-size:23px;color:#5f4288;box-shadow:0 6px 16px #8264a518}.connection-avatar.big{width:100px;height:108px;font-size:40px}.connection-verification{display:flex;align-items:center;gap:8px;font-size:11px;color:#8f6ebb}.connection-hero{display:flex;gap:25px;align-items:center;padding:38px;margin:25px 0;border-radius:30px;background:linear-gradient(120deg,#dfcff58c,#bba3dd22)}.connection-hero h1{font-size:31px;margin:15px 0}.connection-hero .inline{margin-top:20px;font-size:12px}.connection-hero-actions{display:flex;flex-direction:column;gap:12px;margin-inline-start:auto}.connection-details{display:grid;grid-template-columns:.8fr 1.2fr;gap:25px}.connection-details>.panel{padding:28px;align-self:start}.connection-details h2{margin-bottom:23px}.connection-details p{font-size:13px;line-height:1.9}.connection-details dl{display:grid;grid-template-columns:1fr 1.4fr;gap:16px;font-size:12px;margin:24px 0}.connection-details dd{margin:0}.connection-class{padding:25px;margin:20px 0}.connection-class h3{font-size:21px;margin:18px 0}.connection-class strong{display:block;margin:20px 0;font-size:13px}.connection-row{display:flex;gap:18px;align-items:center;flex-wrap:wrap;padding:22px 0;border-bottom:1px solid var(--student-border)}.connection-row>div{flex:1}.review-providers{padding:30px;margin-top:25px}.shared-profile{width:100%;padding:16px;border-radius:12px;border:1px solid var(--student-border);background:var(--student-card);color:var(--student-ink);margin-bottom:25px}.teacher-mini-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.teacher-mini-grid>article{padding:22px}.teacher-mini-grid h3{margin:17px 0}@media(max-width:1000px){.connection-grid{grid-template-columns:repeat(2,1fr)}.connection-hero{flex-wrap:wrap}.connection-details{grid-template-columns:1fr}}@media(max-width:600px){.connection-grid{grid-template-columns:1fr}.connection-hero{padding:24px}.connection-hero-actions{margin:0;width:100%}.teacher-mini-grid{grid-template-columns:1fr}}</style>

<style>.directory-cover{width:100%;aspect-ratio:8/3;object-fit:cover;border-radius:16px;margin-bottom:18px}.connection-avatar img{width:100%;height:100%;border-radius:inherit;object-fit:cover}.directory-hero-cover{width:100%;aspect-ratio:8/3;max-height:350px;background:linear-gradient(125deg,#e9dafa,#ccc2e5);border-radius:26px 26px 0 0;margin-top:24px;overflow:hidden}.directory-hero-cover img{width:100%;height:100%;object-fit:cover}.provider-header-socials+.connection-hero{border-radius:0 0 26px 26px;margin-top:0}.provider-header-socials+.connection-hero .big{border:5px solid var(--student-card,#fff);margin-top:-60px;position:relative;box-shadow:0 8px 20px #6e4a8820}</style>

<style>.directory-empty{padding:48px 28px;text-align:center}.directory-empty h2{font-size:21px;margin:20px 0 12px}.directory-empty p{font-size:13px;line-height:1.8;color:var(--student-muted)}</style>

<style>.provider-header-socials{display:flex;justify-content:flex-end;background:var(--student-card,#fff);padding:12px 24px;min-height:68px}.teacher-mini-grid .provider-social-links{margin:12px 0}.provider-header-socials+.connection-hero .big{margin-top:-110px}@media(max-width:600px){.provider-header-socials{padding-left:135px;padding-right:16px}.provider-header-socials+.connection-hero .big{margin-top:-65px}}</style>